 afterPlayback(){if(this.data?.raid&&!this.g.net.guest)this.resolve()}
 removePlayer(pid){if(this.data?.raid){if(this.g.net.guest)return;this.botTakeovers||=new Set();this.botTakeovers.add(pid);prepareRaidTurn.call(this);if(!this.busy){this.g.net.broadcast({type:'battle-roster',battle:this.data});this.resolve()}return}if(!this.active||this.g.net.guest)return;this.departed.add(pid);this.data.teams=this.data.teams.filter(t=>t.pid!==pid);this.visual.teams=this.visual.teams.filter(t=>t.pid!==pid);delete this.data.actions[pid];this.data.pendingReplacements=(this.data.pendingReplacements||[]).filter(p=>p!==pid);if(!this.busy){this.g.net.broadcast({type:'battle-roster',battle:this.data});this.resolve()}}
